// Extraer los datos del mensaje entrante
const body = $input.item.json;

// El @n8n/chat widget envía:
// { chatInput: "mensaje del usuario", sessionId: "uuid" }
const userMessage = body.chatInput || body.message || body.text || "";
const sessionId = body.sessionId || "";

return {
  userMessage,
  sessionId,
  timestamp: new Date().toISOString()
};

// Transformar resultados de búsqueda en texto legible para el LLM
const response = $input.item.json;

if (!response || !response.results || response.results.length === 0) {
  return {
    found: false,
    message: "No se encontró información relevante en la base de conocimiento de Medicamentum360."
  };
}

const sources = {};
response.results.forEach(r => {
  if (!sources[r.source]) sources[r.source] = [];
  sources[r.source].push(r.content);
});

let contextText = "📚 **Información encontrada en la base de conocimiento:**\n\n";
for (const [source, contents] of Object.entries(sources)) {
  contextText += `### Fuente: ${source}\n`;
  contents.forEach((c, i) => {
    contextText += `${c.trim()}\n\n`;
  });
}

return {
  found: true,
  context: contextText,
  numResults: response.results.length,
  sources: Object.keys(sources)
};

// Respuesta final del agente
const agentOutput = $input.item.json.output || $input.item.json.text || JSON.stringify($input.item.json);
const sessionId = $('parse-input').item.json.sessionId;

return {
  output: agentOutput,
  sessionId: sessionId,
  timestamp: new Date().toISOString()
};
